cd /tmp/claude-0/-home-user/b7d31bcb-5d4a-54b3-81be-c137021a331c/scratchpad/ds-runs/a2e6a2b67d/analysis; python3 -I -c "
import sqlite3,math;c=sqlite3.connect('warehouse.db')
d={}
for w,p,s,cl in c.execute('select date>=\'2026-09-28\',platform||country,sum(searches),sum(clicks) from search_daily group by 1,2'):d[(w,p)]=(s,cl)
segs=sorted({k[1] for k in d})
N0=sum(d[(0,s)][0] for s in segs);N1=sum(d[(1,s)][0] for s in segs)
w0={s:d[(0,s)][0]/N0 for s in segs}
est=0;var=0
for s in segs:
  p0=d[(0,s)][1]/d[(0,s)][0];p1=d[(1,s)][1]/d[(1,s)][0]
  est+=w0[s]*(p1-p0);var+=w0[s]**2*(p0*(1-p0)/d[(0,s)][0]+p1*(1-p1)/d[(1,s)][0])
print(est*100,1.96*math.sqrt(var)*100)
P0=sum(d[(0,s)][1] for s in segs)/N0;P1=sum(d[(1,s)][1] for s in segs)/N1
se=math.sqrt(P0*(1-P0)/N0+P1*(1-P1)/N1);print((P1-P0)*100,1.96*se*100)
print({s:(round(w0[s],3),round(d[(1,s)][0]/N1,3)) for s in segs})
"

